const lf=function normalizeLf(t){return t.replaceAll('\r\n','\n');};
const uniform=function uniformEndings(t){return t===lf(t)||t===lf(t).replaceAll('\n','\r\n');};
const hash=t=>crypto.createHash('sha256').update(t).digest('hex');
